urlset:
{%- for link in links %}

	{{ link.loc }}
	{{ link.lastmod }}
	{%- if link.changefreq %}
	{{ link.changefreq }}
	{%- endif %}
	{%- if link.priority %}
	{{ link.priority }}
	{%- endif %}
	{%- if link.images %}
	{%- for image in link.images %}

		{{ image.loc }}
		{%- if image.title %}
		{{ image.title | e }}
		{%- endif %}

	{%- endfor %}
	{%- endif %}

{%- endfor %}
